sys_ux_client_script.script:
/**
* @param {params} params
* @param {api} params.api
* @param {any} params.event
* @param {any} params.imports
* @param {ApiHelpers} params.helpers
*/
function handler({api, event, helpers, imports}) {
    const mergePARFiltersV2 = imports["global.mergePARFilters"]().v2;
	const { appliedFilters } = event.payload;
	//const { parFilters } = mergePARFiltersV2({}, appliedFilters);
	const temp = {
		filter:null,
		//filter: parFilters,
		columnData: api.state.colmnData
	};
	api.setState("parFilters", ({ currentValue, api }) => {
		const { parFilters } = mergePARFiltersV2(currentValue, appliedFilters);
		temp.filter = parFilters;
		api.setState("filter", JSON.stringify(parFilters));
		api.setState("filter",parFilters);
		return parFilters;
	});

	//api.setState("parFilters",parFilters);
	//api.setState("filter",parFilters);
	api.data.save_user_preference.execute({
        	name: "x_main2_mars_spm_0_u_ptask_chronology",
        	value: JSON.stringify(temp)
    });
}
